//! Std-only smoke runs of the agentd libFuzzer targets
//! (`fuzz/fuzz_targets/`): `control_plane_request` and `safety_feed`, the
//! same harness code (`fuzz/harness/*.rs`, included by path) driven by the
//! deterministic mutator in `fuzz/harness/smoke.rs` over the committed seed
//! corpora. See `fuzz/README.md`. `ROBODR_FUZZ_ITERS` / `ROBODR_FUZZ_SECS`
//! tune the run.
//!
//! The committed seeds are (re)generated by the `regenerate_seeds` test
//! below (run with `--ignored`):
//!
//! * `control_plane_request`: signed v2 requests of every route (fixed SOC
//!   key, timestamp and nonces), each prefixed with the harness's read-step
//!   byte;
//! * `safety_feed`: hand-built RTPS + CDR (the pipeline's synthetic
//!   builders) and safety-socket lines; `safety_feed_seeds_take_the_success_path`
//!   checks they still drive the feed through transitions, so a format
//!   change cannot silently empty the corpus.

mod common;

#[path = "../../robodr-cdr/tests/common/mod.rs"]
mod cdrenc;
#[path = "../../../fuzz/harness/control_plane_request.rs"]
mod control_plane_request;
#[path = "../../../fuzz/harness/safety_feed.rs"]
mod safety_feed;
#[path = "../../../fuzz/harness/smoke.rs"]
mod smoke;

use common::pcap::*;
use control_plane_request as h;
use robodr_agentd::control::{api, auth, evidence, route, Route};
use robodr_blackbox::crypto::to_hex;

const DIR: &str = env!("CARGO_MANIFEST_DIR");
const CP_TARGET: &str = "control_plane_request";
const SF_TARGET: &str = "safety_feed";

// --- control_plane_request ---------------------------------------------------

fn signed(method: &str, target: &str, body: &[u8], nonce: &str) -> Vec<u8> {
    let ts = 1_800_000_000u64;
    let sig = h::soc_key().sign_message(&auth::signing_message(
        method,
        target,
        h::ROBOT,
        h::SOC_ID,
        ts,
        nonce,
        body,
    ));
    let mut out = format!(
        "{method} {target} HTTP/1.1\r\nHost: robot\r\nContent-Type: application/json\r\n\
         Content-Length: {}\r\nX-RoboDR-Key-Id: {}\r\nX-RoboDR-Timestamp: {ts}\r\n\
         X-RoboDR-Nonce: {nonce}\r\nX-RoboDR-Signature: {}\r\n\r\n",
        body.len(),
        h::SOC_ID,
        to_hex(&sig)
    )
    .into_bytes();
    out.extend_from_slice(body);
    out
}

/// Every route, signed, with a read-step byte.
fn cp_seeds() -> Vec<(&'static str, Vec<u8>)> {
    let base = format!("/api/v2/robots/{}", h::ROBOT);
    let submit = serde_json::to_vec(&serde_json::json!({
        "request_id": "robot_restrict_motion:ugv-007:00112233aabbccdd",
        "action": "restrict_motion",
        "parameters": {"max_linear_speed": 0.5, "workspace_zone": "zone-a"},
        "ttl_seconds": 600,
        "reason": "rogue /cmd_vel writer",
        "requested_by": "analyst@soc",
        "source": "soc-a",
        "authority": "request",
    }))
    .unwrap();
    let revert = br#"{"reason": "false positive", "requested_by": "analyst@soc"}"#.to_vec();
    let export = serde_json::to_vec(&serde_json::json!({
        "export_id": "case-42:ev-1",
        "selector": {"finding": {
            "finding_id": "rf1-0011223344556677",
            "evidence": [format!("robodr-blackbox://ugv-007/0/9?sha256={}", "ab".repeat(32))],
            "context_records": 8,
        }},
        "requested_by": "analyst@soc",
        "reason": "case 42",
    }))
    .unwrap();
    let range = br#"{"export_id": "case-42:range", "selector": {"time_range": {"from_ms": 1800000000000, "to_ms": 1800000060000}}, "requested_by": "analyst@soc"}"#.to_vec();
    let with = |step: u8, raw: Vec<u8>| {
        let mut v = vec![step];
        v.extend(raw);
        v
    };
    vec![
        (
            "seed-robot.bin",
            with(0xff, signed("GET", &base, b"", "seed-nonce-000000001")),
        ),
        (
            "seed-submit.bin",
            with(
                6,
                signed(
                    "POST",
                    &format!("{base}/action-requests"),
                    &submit,
                    "seed-nonce-000000002",
                ),
            ),
        ),
        (
            "seed-get.bin",
            with(
                0xff,
                signed(
                    "GET",
                    &format!(
                        "{base}/action-requests/robot_restrict_motion%3Augv-007%3A00112233aabbccdd"
                    ),
                    b"",
                    "seed-nonce-000000003",
                ),
            ),
        ),
        (
            "seed-revert.bin",
            with(
                0,
                signed(
                    "POST",
                    &format!("{base}/action-requests/r-1/revert"),
                    &revert,
                    "seed-nonce-000000004",
                ),
            ),
        ),
        (
            "seed-evidence-inventory.bin",
            with(
                0xff,
                signed(
                    "GET",
                    &format!("{base}/evidence"),
                    b"",
                    "seed-nonce-000000005",
                ),
            ),
        ),
        (
            "seed-evidence-export-finding.bin",
            with(
                33,
                signed(
                    "POST",
                    &format!("{base}/evidence/exports"),
                    &export,
                    "seed-nonce-000000006",
                ),
            ),
        ),
        (
            "seed-evidence-export-time.bin",
            with(
                0xff,
                signed(
                    "POST",
                    &format!("{base}/evidence/exports"),
                    &range,
                    "seed-nonce-000000007",
                ),
            ),
        ),
        (
            "seed-evidence-chunk.bin",
            with(
                0xff,
                signed(
                    "GET",
                    &format!("{base}/evidence/exports/case-42%3Aev-1/chunks/3"),
                    b"",
                    "seed-nonce-000000008",
                ),
            ),
        ),
        (
            "seed-evidence-delete.bin",
            with(
                3,
                signed(
                    "DELETE",
                    &format!("{base}/evidence/exports/case-42%3Aev-1"),
                    b"",
                    "seed-nonce-000000009",
                ),
            ),
        ),
    ]
}

/// The seeds are what the generator writes, and each one takes the
/// success path: read, credentials, signature, route and body all accept
/// it (a format change that turns the corpus into garbage fails here).
#[test]
fn control_plane_seeds_take_the_success_path() {
    let committed = smoke::corpus(DIR, CP_TARGET);
    let mut generated: Vec<(&str, Vec<u8>)> = cp_seeds();
    generated.sort_by_key(|(n, _)| *n);
    assert_eq!(
        committed,
        generated.iter().map(|(_, d)| d.clone()).collect::<Vec<_>>(),
        "fuzz/corpus/{CP_TARGET} differs from the generator; run \
         `cargo test -p robodr-agentd --test fuzz_smoke -- --ignored regenerate_seeds`"
    );
    let keys = [auth::SocKey {
        key_id: h::SOC_ID.into(),
        public: h::soc_key().public_key(),
    }];
    for (name, seed) in &generated {
        let req = h::read(&seed[1..], usize::MAX).unwrap_or_else(|e| panic!("{name}: {e:?}"));
        let c = auth::credentials(&req).unwrap_or_else(|e| panic!("{name}: {e:?}"));
        assert_eq!(auth::verify(&req, &c, &keys, h::ROBOT), Ok(()), "{name}");
        let r =
            route(&req.method, &req.target, h::ROBOT).unwrap_or_else(|e| panic!("{name}: {e:?}"));
        match r {
            Route::Submit => {
                api::parse_submit(&req.body).unwrap();
            }
            Route::Revert(_) => {
                api::parse_revert(&req.body).unwrap();
            }
            Route::EvidenceCreate => {
                evidence::parse_export(&req.body, h::ROBOT).unwrap();
            }
            _ => assert!(req.body.is_empty(), "{name}"),
        }
        // And the harness itself accepts it.
        h::run(seed);
    }
}

#[test]
fn control_plane_request_smoke() {
    let seeds = smoke::corpus(DIR, CP_TARGET);
    smoke::run(CP_TARGET, &seeds, 0xc0de_0002, &h::run);
}

// --- safety_feed --------------------------------------------------------------

const ESTOP_W: [u8; 4] = [0, 0, 0x20, 0x03];
const MODE_W: [u8; 4] = [0, 0, 0x21, 0x03];
const NAME_W: [u8; 4] = [0, 0, 0x22, 0x03];
const BOOL: &str = "std_msgs::msg::dds_::Bool_";
const U8: &str = "std_msgs::msg::dds_::UInt8_";
const STR: &str = "std_msgs::msg::dds_::String_";

fn odom(vx: f64) -> Vec<u8> {
    cdrenc::odometry(
        robodr_cdr::Representation::CdrLe,
        &cdrenc::OdomSpec {
            frame: b"odom",
            child: b"base_link",
            position: [0.0; 3],
            orientation: [0.0, 0.0, 0.0, 1.0],
            pose_cov: [0.0; 36],
            lin: [vx, 0.0, 0.0],
            ang: [0.0; 3],
            twist_cov: [0.0; 36],
        },
    )
}

fn discovery() -> Vec<u8> {
    datagram(
        LEGIT,
        &[
            spdp_sub(LEGIT, &[ROBOT_IP]),
            sedp_writer_sub(LEGIT, ODOM_WRITER, "rt/odom", ODOM),
            sedp_writer_sub(LEGIT, ESTOP_W, "rt/estop", BOOL),
            sedp_writer_sub(LEGIT, MODE_W, "rt/robot_mode", U8),
            sedp_writer_sub(LEGIT, NAME_W, "rt/mode_name", STR),
        ],
    )
}

fn sample(writer: [u8; 4], sn: u32, payload: &[u8]) -> Vec<u8> {
    datagram(LEGIT, &[user_data(writer, [0; 4], sn, payload, true)])
}

fn str_cdr(s: &str) -> Vec<u8> {
    let mut p = vec![0, 1, 0, 0];
    p.extend_from_slice(&(s.len() as u32 + 1).to_le_bytes());
    p.extend_from_slice(s.as_bytes());
    p.push(0);
    while !p.len().is_multiple_of(4) {
        p.push(0);
    }
    p
}

/// `(file name, input)`.
fn sf_seeds() -> Vec<(&'static str, Vec<u8>)> {
    let bus: Vec<(u8, Vec<u8>)> = vec![
        (1, discovery()),
        (1, sample(ESTOP_W, 1, &[0, 1, 0, 0, 0, 0, 0, 0])),
        (1, sample(MODE_W, 2, &[0, 1, 0, 0, 0, 0, 0, 0])),
        (1, sample(NAME_W, 3, &str_cdr("AUTO"))),
        (1, sample(ODOM_WRITER, 4, &odom(0.0))),
        (0, br#"{"state":"idle"}"#.to_vec()),
        safety_feed::tick(10),
        (1, sample(MODE_W, 5, &[0, 1, 0, 0, 1, 0, 0, 0])),
        (1, sample(ODOM_WRITER, 6, &odom(1.5))),
        safety_feed::tick(10),
        (1, sample(ESTOP_W, 7, &[0, 1, 0, 0, 1, 0, 0, 0])),
        (4, br#"{"state":"estop_active"}"#.to_vec()),
        safety_feed::tick(600),
        // The same e-stop sample from a foreign IP: untrusted.
        (2, sample(ESTOP_W, 8, &[0, 1, 0, 0, 1, 0, 0, 0])),
        (0, br#"{"state":"moving_fast"}"#.to_vec()),
        (8, b"not json".to_vec()),
    ];
    let records: Vec<(u8, &[u8])> = bus.iter().map(|(t, b)| (*t, b.as_slice())).collect();
    let custom = serde_json::json!({
        "stale_after_ms": 200,
        "topics": [
            {"topic": "/estop", "type": "std_msgs/msg/Bool",
             "values": {"true": "estop_active", "false": "none"},
             "writers": [safety_feed::LEGIT_HEX]},
            {"topic": "/robot_mode", "type": "std_msgs::msg::dds_::UInt8_",
             "values": {"0": "idle", "1": "moving_slow"}, "writers": [safety_feed::LEGIT_HEX],
             "stale_after_ms": 1000}
        ],
        "socket": {"path": "/run/x.sock"}
    })
    .to_string();
    vec![
        ("seed-default-config.bin", safety_feed::join(b"", &records)),
        (
            "seed-custom-config.bin",
            safety_feed::join(custom.as_bytes(), &records),
        ),
    ]
}

#[test]
fn safety_feed_seeds_take_the_success_path() {
    let committed = smoke::corpus(DIR, SF_TARGET);
    let generated = sf_seeds();
    assert_eq!(committed.len(), generated.len(), "run regenerate_seeds");
    for (name, data) in generated {
        assert!(committed.contains(&data), "{name} differs from fuzz/corpus");
        let (accepted, st, findings) = safety_feed::run_counting(&data);
        assert_eq!(accepted, name.contains("custom"), "{name}");
        assert!(st.socket_reports >= 3, "{name}: {st:?}");
        assert!(st.transitions >= 2, "{name}: {st:?}");
        // Bus samples were decoded and applied, and the foreign-IP one was
        // refused (with a finding).
        assert!(st.applied >= st.socket_reports + 3, "{name}: {st:?}");
        assert!(st.untrusted >= 1 && findings >= 1, "{name}: {st:?}");
    }
}

#[test]
fn safety_feed_smoke() {
    let seeds = smoke::corpus(DIR, SF_TARGET);
    smoke::run(SF_TARGET, &seeds, 0x5afe_0001, &safety_feed::run);
}

/// Regenerates the committed seeds of both targets. Run with
/// `cargo test -p robodr-agentd --test fuzz_smoke -- --ignored regenerate_seeds`.
#[test]
#[ignore = "writes into fuzz/corpus; run manually to refresh seeds"]
fn regenerate_seeds() {
    for (target, seeds) in [(CP_TARGET, cp_seeds()), (SF_TARGET, sf_seeds())] {
        let dir = smoke::corpus_dir(DIR, target);
        std::fs::create_dir_all(&dir).unwrap();
        for (name, data) in seeds {
            std::fs::write(dir.join(name), &data).unwrap();
        }
    }
}
